sp_widget.script:
(function() {
  /* populate the 'data' object */
  /* e.g., data.table = $sp.getValue('table'); */

	//data is the objet used to bind data from server to client

	//From server panel to HTML or Client side
	//usage: data.<any_name>  = assign the server value in server side

	//in client side {{data.<any_name>}} usage of double parenthesis will take the value from the server to client side
	//with same name taaged

	//eg: in server side data.fname = gr.getValue('first_name')
	//to fetch in client side  {{data.fname}}

	var userID = gs.getUserID();

	var getUserDetails = new GlideRecord('sys_user');
	if(getUserDetails.get(userID)){
		data.fname = getUserDetails.getValue('first_name')
	}



	//fetch last task

	data.Inc = []; //array to push all elements
	var getTask = new GlideRecord('task');
	getTask.addEncodedQuery('opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe^numberSTARTSWITHINC')
	getTask.orderByDesc('sys_created_on');
	getTask.query();
	while(getTask.next()){
		//gs.addInfoMessage('Data Found ' + getTask.getValue('number'));
		var incDetails = {}
		incDetails.incNumber = getTask.getValue('number');
		incDetails.incCaller = getTask.getDisplayValue('opened_by');
		incDetails.shortDesc = getTask.getValue('short_description');

		data.Inc.push(incDetails)
	}
	//fetch last task

	gs.addInfoMessage("hello " + data.Inc)



})();
